def sawHeight(trees, need):
    lo, hi = 0, max(trees)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        wood = 0
        for t in trees:
            if t > mid:
                wood += t - mid
        if wood >= need:
            lo = mid
        else:
            hi = mid - 1
    return lo
